pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    let step_ratio = step_index as f64 / total_jobs as f64;
    let dynamic_factor = 1.0 + step_ratio * (1.0 - step_ratio);

    // Lookahead packing bonuses
    let cpu_bonus = if node_residual_cpu > next_job_cpu * 2 {
        0.5
    } else {
        1.0
    };
    let ram_bonus = if node_residual_ram > next_job_ram * 2 {
        0.5
    } else {
        1.0
    };

    // Fine-grained residual fitting penalties
    let cpu_fit_penalty = (node_capacity_cpu - job_cpu) as f64 / node_capacity_cpu as f64;
    let ram_fit_penalty = (node_capacity_ram - job_ram) as f64 / node_capacity_ram as f64;

    // Balance CPU and RAM usage
    let balance_factor = (cpu_norm + ram_norm) / 2.0;

    // Lookahead anticipation bonus
    let lookahead_score = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        0.9 // Strong preference for perfect fit
    } else {
        0.3 // Lower priority if no perfect fit
    };
    let lookahead_factor = (1.0 - step_ratio) * 2.0;

    // Combine fine-grained residual fitting with lookahead anticipation
    let combined_fit_penalty = cpu_fit_penalty * ram_fit_penalty * lookahead_factor + imbalance_penalty * dynamic_factor * lookahead_score;

    let score = (balance_factor * cpu_usage_factor * ram_usage_factor) 
                - combined_fit_penalty 
                + (cpu_bonus + ram_bonus);
    score
}

